def activation_interp(v,is_tanh):
    raw=np.floor(np.asarray(v)*4096+0.5).astype(np.int64)
    pos=np.clip(raw,-16384,16383)+16384
    index,frac=pos>>7,pos&127
    table=TANH if is_tanh else SIGMOID
    return (table[index]+((table[index+1]-table[index])*frac+64)//128)/4096.0
